import UserPreferences from './components/UserPreferences';

// This is a Server Component that fetches user preferences
async function getPreferences() {
  try {
    const response = await fetch(`${process.env.NEXT_PUBLIC_BASE_URL || 'http://localhost:3000'}/api/user-preferences`, {
      cache: 'no-store', // Ensure we get fresh data on each request
    });

    if (!response.ok) {
      throw new Error('Failed to fetch preferences');
    }

    return await response.json();
  } catch (error) {
    console.error('Error fetching preferences:', error);
    return {
      theme: 'light',
      language: 'Unknown'
    };
  }
}

export default async function Home() {
  const { theme, language } = await getPreferences();

  return (
    <main className="container">
      <h1>User Preferences</h1>
      <UserPreferences theme={theme} language={language} />

      <div className="instructions">
        <h3>How to test:</h3>
        <ul>
          <li>To set a theme cookie, you can use browser dev tools or curl: <code>curl -b "theme=dark" http://localhost:3000</code></li>
          <li>The language is automatically detected from your browser&apos;s Accept-Language header</li>
        </ul>
      </div>
    </main>
  );
}

