import { NextRequest, NextResponse } from 'next/server';

export function middleware(request: NextRequest) {
  const response = NextResponse.next();

  // If no theme cookie exists, set a default 'light' theme cookie
  const themeCookie = request.cookies.get('theme');

  if (!themeCookie) {
    // Set a default theme cookie that expires in 30 days
    response.cookies.set('theme', 'light', {
      httpOnly: false, // Allow client-side access
      maxAge: 60 * 60 * 24 * 30, // 30 days
      path: '/',
    });
  }

  return response;
}

// Apply middleware to all routes except API routes
export const config = {
  matcher: ['/((?!api|_next/static|_next/image|favicon.ico).*)'],
};

'use client';

interface ThemeSwitcherProps {
  currentTheme: string;
}

export default function ThemeSwitcher({ currentTheme }: ThemeSwitcherProps) {
  const handleThemeChange = (newTheme: string) => {
    // Set the theme cookie
    document.cookie = `theme=${newTheme}; path=/; max-age=${60 * 60 * 24 * 30}`;

    // Reload the page to reflect changes
    window.location.reload();
  };

  return (
    <div className="theme-switcher">
      <h3>Change Theme:</h3>
      <div className="theme-buttons">
        <button 
          onClick={() => handleThemeChange('light')}
          disabled={currentTheme === 'light'}
          className={currentTheme === 'light' ? 'active' : ''}
        >
          Light
        </button>
        <button 
          onClick={() => handleThemeChange('dark')}
          disabled={currentTheme === 'dark'}
          className={currentTheme === 'dark' ? 'active' : ''}
        >
          Dark
        </button>
      </div>
    </div>
  );
}

